  coverageSummary,
  coverageLedgerCount: coverageSummary.coverageLedgerCount || coverageLedger.length,
  tokenUsage,
  previousTokenUsage,
  tokenSavings,
  estimatedBaselineTokens: tokenSavings.estimatedBaselineTokens,
  estimatedTokensSaved: tokenSavings.estimatedTokensSaved,
  estimatedBaselineCostUsd: tokenSavings.estimatedBaselineCostUsd,
  estimatedCostSavedUsd: tokenSavings.estimatedCostSavedUsd,
  estimatedSavingsPercent: tokenSavings.estimatedSavingsPercent,
  message: [
    addedEpics.length ? addedEpics.length + ' epic' + (addedEpics.length === 1 ? '' : 's') + ' added' : '',
    addedStories.length ? addedStories.length + ' stor' + (addedStories.length === 1 ? 'y' : 'ies') + ' added' : '',
    updatedEpics.length ? updatedEpics.length + ' epic' + (updatedEpics.length === 1 ? '' : 's') + ' updated' : '',
    updatedStories.length ? updatedStories.length + ' stor' + (updatedStories.length === 1 ? 'y' : 'ies') + ' updated' : '',
  ].filter(Boolean).join(', ') || 'No backlog changes needed',
};

return [{
  json: {
    ...input,
    result,
    output: {
      settingsVersion: input.settingsVersion || null,
      destination: { type: 'jira_confluence', projectId: input.projectId || null },
      url: confluenceUrl,
      documentUrl: confluenceUrl,
      confluence: result.confluence || null,
      epics: currentEpics,
      stories: currentStories,
      professionalGenerator: true,
      generationMode,
      updateContext: generationMode === 'update' ? {
        previousJobId: updateContext.previousJobId || input.updateOfJobId || null,
        previousConfluencePageId: updateContext.previousConfluencePageId || null,
        previousConfluenceUrl: updateContext.previousConfluenceUrl || null,
        previousBacklogBaselineCounts: updateSummary.previousBacklogBaselineCounts,
        previousTokenUsage,
      } : null,
      updateSummary,
      tokenSavings,
      tokenUsage,
      qualityGate: { ...(result.qualityGate || {}), coverageLedger, coverageSummary },
      coverageLedger,
      coverageSummary,
      batchPlan: result.batchPlan || result.qualityGate?.batchPlan || null,
      batchSummary: result.batchSummary || result.qualityGate?.batchSummary || null,
      jira: result.jira || null,
      wordCount: result.wordCount || 0,
      tokensInput: tokenUsage.input,
      tokensOutput: tokenUsage.output,
      tokensTotal: tokenUsage.total,
      estimatedCostUsd: tokenUsage.estimatedCostUsd,
      promptLibraryVersion: result.promptLibraryVersion || null,
      sourceCoverage: result.sourceCoverage || [],
      retrievalEvidenceCount: result.retrievalEvidenceCount || 0,
      retrievalQuality: result.retrievalQuality || null,
      progress: result.progress || { stage: 'published', stageLabel: 'Published to Jira and Confluence', progressPercent: 100, coverage: coverageSummary },
    }
  }
}];

const item = $('Build Backlog Completion Output').first().json;
const output = item.output && typeof item.output === 'object' ? item.output : {};

function array(value) {
  return Array.isArray(value) ? value.filter(entry => entry && typeof entry === 'object') : [];
}
function numberValue(...values) {
  for (const value of values) {
    const number = Number(value);
    if (Number.isFinite(number)) return number;
  }
  return 0;
}
function coverageSummaryFromLedger(rows) {
  const summary = {
    mode: 'enforced',
    version: 'backlog-coverage-ledger-v1',
    gateStatus: 'passed',
    coverageLedgerCount: rows.length,
    coveredCount: 0,
    partialCount: 0,
    missingCount: 0,
    unknownCount: 0,
    excludedCount: 0,
    uncoveredCount: 0,
    blockingUncoveredCount: 0,
    missingItems: [],
  };
  for (const row of rows) {
    const status = String(row.coverageStatus || row.status || '').toLowerCase();
    if (status.includes('cover')) summary.coveredCount += 1;
    else if (status.includes('exclude')) summary.excludedCount += 1;
    else if (status.includes('partial') || status.includes('review')) {
      summary.partialCount += 1;
      summary.missingItems.push(row);
    } else {
      summary.missingCount += 1;
      summary.missingItems.push(row);
    }
  }
  summary.uncoveredCount = summary.partialCount + summary.missingCount + summary.unknownCount;
  summary.blockingUncoveredCount = summary.missingCount + summary.unknownCount;
  if (summary.blockingUncoveredCount) summary.gateStatus = 'failed';
  else if (summary.partialCount) summary.gateStatus = 'warning';
  return summary;
}

const tokenUsage = output.tokenUsage || output.updateSummary?.tokenUsage || {
  source: output.updateSummary?.tokenUsage?.source || 'estimated',
  input: numberValue(output.tokensInput),
  output: numberValue(output.tokensOutput),
  total: numberValue(output.tokensTotal),
  estimatedCostUsd: numberValue(output.estimatedCostUsd),
};
tokenUsage.tokensInput = numberValue(tokenUsage.tokensInput, tokenUsage.input);
tokenUsage.tokensOutput = numberValue(tokenUsage.tokensOutput, tokenUsage.output);
tokenUsage.tokensTotal = numberValue(tokenUsage.tokensTotal, tokenUsage.total);
tokenUsage.input = numberValue(tokenUsage.input, tokenUsage.tokensInput);
tokenUsage.output = numberValue(tokenUsage.output, tokenUsage.tokensOutput);
tokenUsage.total = numberValue(tokenUsage.total, tokenUsage.tokensTotal);
tokenUsage.estimatedCostUsd = numberValue(tokenUsage.estimatedCostUsd, output.estimatedCostUsd);

const coverageLedger = array(output.coverageLedger).length
  ? array(output.coverageLedger)
  : array(output.qualityGate?.coverageLedger);
const coverageSummary = output.coverageSummary || output.qualityGate?.coverageSummary || coverageSummaryFromLedger(coverageLedger);
const tokenSavings = output.tokenSavings || output.updateSummary?.tokenSavings || null;

item.output = {
  ...output,
  tokenUsage,
  tokenSavings,
  coverageLedger,
  coverageSummary,
  qualityGate: {
    ...(output.qualityGate || {}),
    coverageLedger,
    coverageSummary,
  },
  updateSummary: output.updateSummary ? {
    ...output.updateSummary,
    tokenUsage: output.updateSummary.tokenUsage || tokenUsage,
    tokenSavings: output.updateSummary.tokenSavings || tokenSavings,
    coverageSummary: output.updateSummary.coverageSummary || coverageSummary,
    coverageLedgerCount: output.updateSummary.coverageLedgerCount || coverageSummary.coverageLedgerCount || coverageLedger.length,
  } : output.updateSummary,
  tokensInput: tokenUsage.input,
  tokensOutput: tokenUsage.output,
  tokensTotal: tokenUsage.total,
  estimatedCostUsd: tokenUsage.estimatedCostUsd,
};

return [{ json: item }];

const source = $input.first()?.json || {};
const job = source.job || source;
const error = source.error || source.output?.error || source;
const documentType = String(job.documentType || job.document_type || job.doc_type || '').toLowerCase();
const isBacklog = documentType === 'user_stories' || documentType === 'epics_user_stories';
const messageParts = [
  error.message,
  error.error?.message,
  error.description,
  error.errorDescription,
  error.errorDetails?.rawErrorMessage?.join?.(' '),
  source.message,
].filter(Boolean);
const backendMessage = messageParts.join(' | ') || 'Generation workflow failed before producing an output.';
return [{
  json: {
    ...source,
    job,
    output: {
      status: 'failed',
      errorType: isBacklog ? 'PROFESSIONAL_BACKLOG_FAILED' : 'SHARED_GENERATOR_FAILED',
      message: backendMessage,
      backendMessage,
      failedAt: error.node?.name || error.nodeName || error.name || 'Shared generator subworkflow',
      remediation: isBacklog
        ? 'Review the Jira/backlog generation workflow error, then regenerate with fixes.'
        : 'Review the shared document generator workflow error, then regenerate with fixes.',
    },
  },
}];
